const html=$input.item.json.data||'';
const wd=$('Webhook: Deep Scrape').item.json.body;
const wsUrl=wd.websiteUrl||'';
let origin='https://example.com';
try{origin=new URL(wsUrl).origin;}catch(e){}
const baseUrl=wsUrl.replace(/\/[^/]*$/,'').replace(/\/$/,'');
const abs=u=>{if(!u)return null;let s=String(u).trim();if(!s||s.startsWith('data:'))return null;if(s.startsWith('//'))return 'https:'+s;if(s.startsWith('/'))return origin+s;if(!s.startsWith('http'))return baseUrl+'/'+s;return s;};


// ── Öffnungszeiten ────────────────────────────────────────────
const DAYS7=['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
const DAY_ALIAS={monday:'monday',mon:'monday',mo:'monday',montag:'monday',tuesday:'tuesday',tue:'tuesday',tues:'tuesday',tu:'tuesday',di:'tuesday',dienstag:'tuesday',wednesday:'wednesday',wed:'wednesday',we:'wednesday',mi:'wednesday',mittwoch:'wednesday',thursday:'thursday',thu:'thursday',thur:'thursday',th:'thursday',do:'thursday',donnerstag:'thursday',friday:'friday',fri:'friday',fr:'friday',freitag:'friday',saturday:'saturday',sat:'saturday',sa:'saturday',samstag:'saturday',sonnabend:'saturday',sunday:'sunday',sun:'sunday',su:'sunday',so:'sunday',sonntag:'sunday'};
const normDay=t=>DAY_ALIAS[String(t).trim().toLowerCase().replace(/^https?:\/\/schema\.org\//,'').replace(/[.,;]+$/,'')]||null;
const normTime=t=>{const m=String(t).trim().match(/^(\d{1,2})[:.]?(\d{2})$/);if(!m)return null;const h=+m[1],mi=+m[2];if(h>24||mi>59)return null;return String(h).padStart(2,'0')+':'+m[2];};
const expandDays=spec=>{const out=[];for(const part of String(spec).split(/[,/]|\su(?:nd)?\s|\s&\s/i)){const rng=part.split(/\s*(?:-|–|—|bis|to)\s*/i).filter(Boolean);if(rng.length===2){const a=normDay(rng[0]),b=normDay(rng[1]);if(a&&b){const st=DAYS7.indexOf(a),en=DAYS7.indexOf(b);for(let i=0;i<7;i++){const ix=(st+i)%7;out.push(DAYS7[ix]);if(ix===en)break;}continue;}}const one=normDay(part);if(one)out.push(one);}return [...new Set(out)];};
const parseHoursLine=line=>{const out={};const times=[...String(line).matchAll(/(\d{1,2}[:.]\d{2})/g)].map(m=>m[1]);if(times.length<2)return out;const o=normTime(times[0]),c=normTime(times[1]);if(!o||!c)return out;
// Ohne erkennbare Tagesangabe wird NICHTS angenommen – raten wäre genau der
// Fehler, den diese Änderung behebt.
for(const d of expandDays(String(line).slice(0,String(line).indexOf(times[0]))))out[d]={open:o,close:c,closed:false};return out;};
const parseHours=node=>{const out={};const spec=node.openingHoursSpecification;for(const e of(Array.isArray(spec)?spec:spec?[spec]:[])){const o=normTime(e&&e.opens),c=normTime(e&&e.closes);if(!o||!c)continue;const raw=e.dayOfWeek;for(const d of(Array.isArray(raw)?raw:raw?[raw]:[])){const k=normDay(d);if(k)out[k]={open:o,close:c,closed:false};}}
const plain=node.openingHours;for(const line of(Array.isArray(plain)?plain:plain?[plain]:[])){for(const [d,h] of Object.entries(parseHoursLine(line)))if(!out[d])out[d]=h;}return out;};

// ── JSON-LD ────────────────────────────────────────────────────
// GEÄNDERT gegenüber der Vorfassung, beide Fehler an kleiner-kiepenkerl.de
// nachgewiesen:
//  1. @graph wurde nicht durchlaufen. Die Seite legt ALLES in einen @graph –
//     Adresse, Öffnungszeiten und Bewertung waren dadurch unerreichbar.
//  2. @type ist dort ['Restaurant','Organization'], also ein ARRAY. Ein
//     .includes(item['@type']) auf ein Array trifft nie zu.
// Ergebnis vorher: address = '' bei einer Seite, die eine vollständige
// PostalAddress ausliefert.
const jldBlocks=[...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
const ldNodes=[];
const collect=n=>{if(!n||typeof n!=='object')return;if(Array.isArray(n))return n.forEach(collect);ldNodes.push(n);if(Array.isArray(n['@graph']))n['@graph'].forEach(collect);if(n.hasMenu)collect(n.hasMenu);};
for(const b of jldBlocks){try{collect(JSON.parse(b[1].trim()));}catch(e){}}
const isType=(node,...want)=>{const t=node['@type'];const list=Array.isArray(t)?t:[t];return list.some(x=>typeof x==='string'&&want.includes(x.replace('http://schema.org/','')));};

let jld={},menuItems=[],openingHours={},address='',lat=null,lng=null,ratingValue=null,reviewCount=null,ldLogo=null,sameAs=[];
const BIZ=['Restaurant','FoodEstablishment','Bakery','CafeOrCoffeeShop','BarOrPub','FastFoodRestaurant','LocalBusiness','Organization'];
for(const item of ldNodes){
  if(isType(item,...BIZ)){
    jld={...jld,...item};
    if(item.address){
      // postalCode war zuvor nicht dabei – "Spiekerhof 47, Münster" statt
      // "Spiekerhof 47, 48143 Münster".
      const a=item.address;
      if(typeof a==='string')address=a.trim();
      else{const ort=[a.postalCode,a.addressLocality].filter(Boolean).join(' ');address=[a.streetAddress,ort].filter(Boolean).join(', ');}
    }
    if(item.geo){lat=item.geo.latitude??lat;lng=item.geo.longitude??lng;}
    if(item.aggregateRating){ratingValue=item.aggregateRating.ratingValue??ratingValue;reviewCount=item.aggregateRating.reviewCount??reviewCount;}
    if(item.logo)ldLogo=typeof item.logo==='string'?item.logo:item.logo.url;
    if(item.sameAs)sameAs.push(...(Array.isArray(item.sameAs)?item.sameAs:[item.sameAs]));
    // GEÄNDERT: Der vorherige Ausdruck erwartete "Mo-Su 11:30-23:00".
    // kleiner-kiepenkerl.de liefert "Monday,Tuesday,…,Sunday 11:30-23:00" –
    // ausgeschrieben und kommagetrennt. Er traf nie, es kamen null Tage
    // heraus, und der nachgelagerte Knoten füllte STANDARDWERTE ein
    // (12:00–22:00). Veröffentlicht wurden damit ERFUNDENE Öffnungszeiten.
    Object.assign(openingHours,parseHours(item));
  }
  if(isType(item,'Menu')){
    for(const s of(item.hasMenuSection||[])){const cat=s.name||'Hauptgerichte';for(const e of(s.hasMenuItem||s.hasMenuSection||[])){if(e.name){const o=e.offers||e.offer||{};menuItems.push({id:`ld-${e.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,40)}`,name:e.name,description:e.description||'',category:cat,price:o.price?String(o.price):''});}}}
  }
}

// ── Meta ──────────────────────────────────────────────────────
const gm=n=>{const m=html.match(new RegExp(`<meta[^>]+(?:property|name)=["']${n}["'][^>]+content=["']([^"']+)["']`,'i'))||html.match(new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${n}["']`,'i'));return m?m[1].trim():null;};
const ogTitle=gm('og:title')||gm('title'),ogDesc=gm('og:description')||gm('description'),ogImage=gm('og:image'),themeColor=gm('theme-color');

// ── Logo ──────────────────────────────────────────────────────
// NEU. Zuvor kam ein Logo im ganzen Ablauf nicht vor – im Gegenteil, Bilder
// mit "logo" im Namen wurden aus der Galerie GEFILTERT und danach verworfen.
// Ohne Logo sieht jede erzeugte Seite gleich aus.
let logoUrl=abs(ldLogo);
if(!logoUrl){for(const rel of['apple-touch-icon','icon']){const t=html.match(new RegExp(`<link[^>]+rel=["'][^"']*${rel}[^"']*["'][^>]*>`,'i'));const h=t&&t[0].match(/href=["']([^"']+)["']/i);if(h){logoUrl=abs(h[1]);break;}}}
if(!logoUrl){for(const img of html.matchAll(/<img[^>]*>/gi)){if(!/logo/i.test(img[0]))continue;const m=img[0].match(/\bdata-src=["']([^"']+)["']/i)||img[0].match(/\bsrc=["']([^"']+)["']/i);if(m){logoUrl=abs(m[1]);break;}}}
if(!logoUrl)logoUrl=abs(ogImage);

// ── Reservierungssystem ───────────────────────────────────────
// NEU und der wichtigste Zugewinn. hasReservation wurde zuvor ÜBERHAUPT NICHT
// gesetzt – deshalb kam es als null zurück, obwohl kleiner-kiepenkerl.de ein
// OpenTable-Widget einbindet (rid=169746).
// Ein Link, der wörtlich auf der Seite steht, gilt mehr als eine aus der
// Kennung zusammengebaute Adresse: Der funktioniert nachweislich.
const RES=[
 ['OpenTable',/opentable\.(?:de|com|co\.uk|at|ch)/i,/opentable\.(de|com|co\.uk|at|ch)\/widget\/reservation\/loader\?[^"'\s]*\brid=(\d+)/i],
 ['Quandoo',/quandoo\.(?:de|com|at|ch)/i,null],
 ['resmio',/resmio\.com/i,null],
 ['TheFork',/thefork\.(?:de|com)|lafourchette\.com|bookatable\./i,null],
 ['DISH Reservation',/reservation\.dish\.co/i,null],
 ['SevenRooms',/sevenrooms\.com/i,null],
 ['formitable',/formitable\.com/i,null],
 ['Tischwunsch',/tischwunsch\.de/i,null],
 ['aleno',/aleno\.(?:me|com)/i,null],
 ['Zenchef',/zenchef\.com/i,null],
 ['resengo',/resengo\.com/i,null],
];
const anchors=[...html.matchAll(/<a[^>]+href=["']([^"']+)["']/gi)].map(m=>m[1]);
let reservationUrl=null,reservationProvider=null;
// Ein EINGEBETTETES Widget belegt das tatsächlich benutzte System stärker als
// ein Link. kleiner-kiepenkerl.de bindet OpenTable ein (das sichtbare
// Buchungsfeld) UND verlinkt nebenbei auf Tischwunsch – nach Links zuerst zu
// suchen lieferte Tischwunsch, nicht das System vor den Augen des Gastes.
for(const [name,host,idRx] of RES){
  const embedded=idRx?html.match(idRx):null;
  const anyEmbed=[...html.matchAll(/<(?:script|iframe)[^>]+(?:src|data-src)=["']([^"']+)["']/gi)].some(m=>host.test(m[1]));
  if(!embedded&&!anyEmbed)continue;
  const own=anchors.find(h=>host.test(h));
  if(own){reservationUrl=abs(own);reservationProvider=name;break;}
  if(embedded&&name==='OpenTable'){reservationUrl=`https://www.opentable.${embedded[1]}/restref/client/?rid=${embedded[2]}&restref=${embedded[2]}&lang=de-DE`;reservationProvider=name;break;}
  break; // eingebunden, aber ohne Ziel: lieber nichts als ein toter Knopf
}
if(!reservationUrl){for(const [name,host] of RES){const hit=anchors.find(h=>host.test(h));if(hit){reservationUrl=abs(hit);reservationProvider=name;break;}}}
const hasReservation=Boolean(reservationUrl);

// ── Soziale Netze ─────────────────────────────────────────────
const social={};
for(const u of[...sameAs,...anchors]){const s=String(u);if(!social.instagram&&/instagram\.com\//i.test(s))social.instagram=abs(s);if(!social.facebook&&/facebook\.com\//i.test(s))social.facebook=abs(s);}

// ── Farben aus Inline-CSS ─────────────────────────────────────
const allCss=(html.match(/<style[^>]*>([\s\S]*?)<\/style>/gi)||[]).join('')+(html.match(/style=["']([^"']*)["']/gi)||[]).join('');
const cf={};let hm;const hRex=/#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})\b/g;
while((hm=hRex.exec(allCss))!==null){let c=hm[0].toLowerCase();if(c.length===4)c='#'+c[1]+c[1]+c[2]+c[2]+c[3]+c[3];const r=parseInt(c.slice(1,3),16),g=parseInt(c.slice(3,5),16),b=parseInt(c.slice(5,7),16),mx=Math.max(r,g,b),mn=Math.min(r,g,b),lt=(mx+mn)/2/255,sat=mx===mn?0:(mx-mn)/(mx+mn<255?mx+mn:510-mx-mn);if(lt>0.1&&lt<0.95&&sat>0.2)cf[c]=(cf[c]||0)+1;}
const sortedColors=Object.entries(cf).sort((a,b)=>b[1]-a[1]).slice(0,6).map(e=>e[0]);
if(themeColor&&!sortedColors.includes(themeColor))sortedColors.unshift(themeColor);

// ── CSS Links ─────────────────────────────────────────────────
const cssLinks=[...html.matchAll(/<link[^>]+rel=["']stylesheet["'][^>]+href=["']([^"']+)["']/gi)].map(m=>abs(m[1])).filter(u=>u&&!u.includes('font')&&!u.includes('bootstrap')&&!u.includes('fontawesome')).slice(0,2);

// ── Bilder ────────────────────────────────────────────────────
const imgUrls=[];if(ogImage)imgUrls.push(ogImage);
for(const img of html.matchAll(/<img[^>]+src=["']([^"']+)["'][^>]*>/gi)){const s0=img[1];if(s0.startsWith('data:')||s0.includes('icon')||s0.includes('logo')||s0.includes('svg'))continue;const s=abs(s0);if(s&&!imgUrls.includes(s))imgUrls.push(s);}

// ── Kontakt ───────────────────────────────────────────────────
const emailM=html.match(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/i);
const phoneM=html.match(/(?:tel:|\+49|0049|0)(?:\s?[\d-]){7,14}/);
const businessName=wd.businessName||ogTitle||'';
const typeRaw=(Array.isArray(jld['@type'])?jld['@type'].join(' '):(jld['@type']||'')).toLowerCase();
let businessType=wd.businessType||'restaurant';
if(typeRaw.includes('bakery'))businessType='bakery';else if(typeRaw.includes('cafe'))businessType='cafe';else if(typeRaw.includes('bar'))businessType='bar';else if(typeRaw.includes('pizza'))businessType='pizzeria';

// ── menuUrl bereinigen ────────────────────────────────────────
let rawMenu = wd.menuUrl || '';
if (Array.isArray(rawMenu)) rawMenu = rawMenu[0] || '';
rawMenu = String(rawMenu);
const menuUrl = rawMenu.replace(/^[{\['"|]+|[}\]'"|]+$/g,'').split(',')[0].trim();
const menuExt = (menuUrl.split('?')[0].split('#')[0].split('.').pop()||'').toLowerCase();
const isMenuImage = ['jpg','jpeg','png','webp','gif','bmp','tiff','tif'].includes(menuExt);
const isMenuPdf = menuExt === 'pdf';
const isMenuPage = ['html','htm','php','asp','aspx'].includes(menuExt)||(!menuExt||menuExt.length>5);

return{businessName,businessType,slogan:(jld.slogan||'').slice(0,120),description:(ogDesc||jld.description||'').slice(0,500),email:wd.email||(emailM?emailM[0]:null),phone:wd.phone||(phoneM?phoneM[0].replace(/^tel:/,'').trim():null),address,latitude:lat,longitude:lng,ratingValue,reviewCount,gallery:imgUrls.slice(0,15),menuItems,openingHours,colorsFromHtml:sortedColors,cssLinks,instagramUrl:wd.instagramUrl||social.instagram||null,menuUrl:menuUrl||null,isMenuImage,isMenuPdf,isMenuPage,websiteUrl:wsUrl,googleSearchQuery:wd.googleSearchQuery||`${businessName} Restaurant`,ogImage,logoUrl,hasReservation,reservationUrl,reservationProvider,socialMedia:social};

const css=$input.item.json.data||'';
const d=$('Code: Parse HTML').item.json;
const cf={};let m;const hRex=/#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})\b/g;
while((m=hRex.exec(css))!==null){let c=m[0].toLowerCase();if(c.length===4)c='#'+c[1]+c[1]+c[2]+c[2]+c[3]+c[3];const r=parseInt(c.slice(1,3),16),g=parseInt(c.slice(3,5),16),b=parseInt(c.slice(5,7),16),mx=Math.max(r,g,b),mn=Math.min(r,g,b),lt=(mx+mn)/2/255,sat=mx===mn?0:(mx-mn)/(mx+mn<255?mx+mn:510-mx-mn);if(lt>0.08&&lt<0.96&&sat>0.15)cf[c]=(cf[c]||0)+1;}
const vars=[...css.matchAll(/--[a-z-]*color[^:]*:\s*(#[0-9a-fA-F]{3,6})/gi)].map(m2=>m2[1].toLowerCase());
const cssColors=[...vars,...Object.entries(cf).sort((a,b)=>b[1]-a[1]).slice(0,8).map(e=>e[0])].filter((c,i,arr)=>arr.indexOf(c)===i).slice(0,8);
const allColors=[...new Set([...d.colorsFromHtml,...cssColors])].slice(0,6);
const sorted=allColors.slice().sort((a,b)=>{const lum=c=>{c=c.replace('#','');return 0.2126*parseInt(c.slice(0,2),16)+0.7152*parseInt(c.slice(2,4),16)+0.0722*parseInt(c.slice(4,6),16);};return lum(a)-lum(b);});
return{...d,colors:allColors,primaryColor:sorted[0]||'#1a1a2e',secondaryColor:sorted[Math.floor(sorted.length/2)]||'#e94560',backgroundColor:sorted[sorted.length-1]||'#f5f5f5',fontFamily:css.includes('serif')&&!css.includes('sans-serif')?'serif':'sans-serif',template:'minimalist'};

const raw=$input.item.json;
const d=$('IF: Ist Bild?').item.json;
let b64='';
try{b64=Buffer.from(raw.data,'binary').toString('base64');}catch(e){}
const ext=(d.menuUrl.split('?')[0].split('.').pop()||'').toLowerCase();
const mime={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',bmp:'image/bmp',tiff:'image/tiff',tif:'image/tiff'};
return{...d,imageBase64:b64,imageMimeType:mime[ext]||'image/jpeg'};

