const vr=$input.item.json;
const d=$('Code: Bild → Base64').item.json;
const txt=vr.candidates?.[0]?.content?.parts?.[0]?.text||'';
const items=txt?parseMenu(txt):[];
return{...d,menuItems:items.length?items:(d.menuItems||[]),menuSource:items.length?'image_ocr':(txt?'image_ocr_no_menu':'image_ocr_failed')};
function parseMenu(text){const items=[],lines=text.split(/\n|\r/);let cat='Hauptgerichte';const cats=[[/Vorspeise|Antipasti|Starter|Kleinigkeiten/i,'Vorspeisen'],[/Suppe|Soup|Eintopf/i,'Suppen'],[/Salat|Salad/i,'Salate'],[/Haupt|Main|Fleisch|Fisch|Geflügel|Grill/i,'Hauptgerichte'],[/Pizza/i,'Pizza'],[/Pasta|Nudel|Spaghetti/i,'Pasta'],[/Burger/i,'Burger'],[/Sandwich|Wrap|Toast/i,'Sandwiches'],[/Dessert|Nachspeise|Kuchen|Eis/i,'Desserts'],[/Getränk|Drink|Wein|Bier|Kaffee|Cocktail/i,'Getränke'],[/Frühstück|Breakfast/i,'Frühstück'],[/Snack|Beilage/i,'Snacks']];const pRx=/(\d{1,3}[,.]\d{2})\s*€?|€\s*(\d{1,3}[,.]\d{2})/;for(let i=0;i<lines.length;i++){const l=lines[i].trim();if(!l||l.length<2)continue;if(l.length<45&&!pRx.test(l))for(const[rx,c]of cats)if(rx.test(l)){cat=c;break;}const pm=l.match(pRx);if(!pm)continue;const price=(pm[1]||pm[2]).replace(',','.');if(parseFloat(price)<=0||parseFloat(price)>300)continue;let name=l.slice(0,pm.index).replace(/€/g,'').replace(/^[.\-–—|*#]+|[.\-–—|*#]+$/g,'').replace(/\s*\([A-Z,\d\s]{1,20}\)\s*$/,'').trim();if(name.length<2||name.length>80)continue;const nl=(lines[i+1]||'').trim();let desc='';if(nl&&!pRx.test(nl)&&nl.length>3&&nl.length<120){desc=nl;i++;}items.push({id:`img-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,name,description:desc,category:cat,price});}return items;}

const html=$input.item.json.data||'';
const d=$('IF: Ist Webseite?').item.json;
const items=[];
for(const block of html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)){try{const p=JSON.parse(block[1].trim());for(const item of(Array.isArray(p)?p:[p])){if(item['@type']==='Menu'){for(const s of(item.hasMenuSection||[])){const cat=s.name||'Hauptgerichte';for(const e of(s.hasMenuItem||[])){if(e.name){const o=e.offers||{};items.push({id:`wp-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,name:e.name,description:e.description||'',category:cat,price:o.price?String(o.price):''});}}}}}}catch(e){}}
if(items.length===0){const text=html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ').replace(/&auml;/g,'ä').replace(/&ouml;/g,'ö').replace(/&uuml;/g,'ü').replace(/&szlig;/g,'ß').replace(/\s{2,}/g,'\n').trim();
const cats=[[/Vorspeise|Antipasti|Starter/i,'Vorspeisen'],[/Suppe|Soup/i,'Suppen'],[/Salat|Salad/i,'Salate'],[/Haupt|Main|Fleisch|Fisch|Geflügel/i,'Hauptgerichte'],[/Pizza/i,'Pizza'],[/Pasta|Nudel/i,'Pasta'],[/Burger/i,'Burger'],[/Dessert|Nachspeise|Kuchen/i,'Desserts'],[/Getränk|Drink|Wein|Bier/i,'Getränke']];const pRx=/(\d{1,3}[,.]\d{2})\s*€?|€\s*(\d{1,3}[,.]\d{2})/;let cat='Hauptgerichte';const lines=text.split('\n');
for(let i=0;i<lines.length;i++){const l=lines[i].trim();if(!l||l.length<2)continue;if(l.length<45&&!pRx.test(l))for(const[rx,c]of cats)if(rx.test(l)){cat=c;break;}const pm=l.match(pRx);if(!pm)continue;const price=(pm[1]||pm[2]).replace(',','.');if(parseFloat(price)<=0||parseFloat(price)>300)continue;let name=l.slice(0,pm.index).replace(/€/g,'').replace(/^[.\-–—|*]+|[.\-–—|*]+$/g,'').replace(/\s*\([A-Z,\d\s]{1,20}\)\s*$/,'').trim();if(name.length<2||name.length>80)continue;const nl=(lines[i+1]||'').trim();let desc='';if(nl&&!pRx.test(nl)&&nl.length>3&&nl.length<120){desc=nl;i++;}items.push({id:`wp-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,name,description:desc,category:cat,price});}}
return{...d,menuItems:items.length?items:(d.menuItems||[]),menuSource:items.length?'webpage':'webpage_none'};

const d=$('IF: Ist Webseite?').item.json;
let pdfText='';
try{
  const raw=Buffer.from($input.item.json.data,'binary').toString('latin1');
  const chunks=[];
  for(const block of raw.matchAll(/BT([\s\S]*?)ET/g)){const c=block[1];chunks.push(...[...c.matchAll(/\(([^)]{1,300})\)\s*Tj/g)].map(m=>m[1]));chunks.push(...[...c.matchAll(/\[([^\]]+)\]\s*TJ/g)].map(m=>m[1].replace(/\([^)]*\)|\d+/g,s=>s.startsWith('(')?s.slice(1,-1):' ')));}
