const bParts=igDesc?.split(' - ');
const bio=bParts&&bParts.length>1?bParts[bParts.length-1].trim():null;
const igImages=[igImage].filter(Boolean);
try{const sd=html.match(/window\._sharedData\s*=\s*({[\s\S]*?});/);if(sd){const u=JSON.parse(sd[1])?.entry_data?.ProfilePage?.[0]?.graphql?.user;if(u)for(const e of(u.edge_owner_to_timeline_media?.edges?.slice(0,9)||[])){const url=e.node?.display_url||e.node?.thumbnail_src;if(url&&!igImages.includes(url))igImages.push(url);}}}catch(e){}
return{...base,instagramBio:bio||base.description,instagramFollowers:fm?fm[1]:null,instagramImages:igImages,gallery:[...new Set([...base.gallery,...igImages])].slice(0,20)};

const gd=$input.item.json;
