let gmaps={};
try{const c=gd.candidates?.[0]||gd.result||{};
let oh=prev.openingHours||{};
if(c.opening_hours?.periods&&Object.keys(oh).length===0){const dn=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];for(const p of c.opening_hours.periods){const d=dn[p.open?.day];if(d){const o=(p.open?.time||'1200').replace(/(\d{2})(\d{2})/,'$1:$2'),cl=(p.close?.time||'2200').replace(/(\d{2})(\d{2})/,'$1:$2');oh[d]={open:o,close:cl,closed:false};}}for(const d of['monday','tuesday','wednesday','thursday','friday','saturday','sunday'])if(!oh[d])oh[d]={open:'12:00',close:'22:00',closed:true};}
