const days=['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];

// ── Öffnungszeiten ────────────────────────────────────────────
// GEÄNDERT. Vorher stand hier:
//   for(const d of days)oh[d]=m.openingHours?.[d]||{open:'12:00',close:'22:00',...}
// Damit bekam JEDE Seite eine vollständige Woche – auch wenn nichts erkannt
