// keine – deshalb wird jetzt nur übernommen, was tatsächlich dasteht.
const oh={};
for(const d of days){const v=m.openingHours&&m.openingHours[d];if(v&&v.open&&v.close)oh[d]=v;}

const seen=new Set();
const menuItems=(m.menuItems||[]).filter(item=>{const k=item.name?.toLowerCase().trim();if(!k||seen.has(k))return false;seen.add(k);return true;});
let template='minimalist';
if(['bar','steakhouse'].includes(m.businessType))template='bold';
else if(m.businessType==='restaurant'&&m.gmapsRating>=4.5)template='classic';

const suggestedConfig={
  businessName:m.businessName||'',
