};

let score=40;
if(menuItems.length>=5)score+=25;else if(menuItems.length>0)score+=15;
if(suggestedConfig.gallery.length>=3)score+=15;
// Nur echte Öffnungszeiten zählen – vorher gab es die Punkte immer, weil die
